import { useEffect, useState } from 'react'
function Box() {
  useState(() => {
    console.log(1)
    return 1
  })
  return null
}
function App() {
  const [k, setK] = useState(0)
  useEffect(() => {
    setK(1)
  }, [])
  return <Box key={k} />
}

