import { useEffect, useState } from 'react'
function A() {
  const [n] = useState(1)
  console.log(n)
  return null
}
function B() {
  const [n] = useState(2)
  console.log(n)
  return null
}
function App() {
  const [flag, setFlag] = useState(true)
  useEffect(() => {
    setFlag(false)
  }, [])
  return flag ? <A /> : <B />
}

