import { useEffect, useState } from 'react'
function Child({ n }) {
  const [prev, setPrev] = useState(n)
  const [value, setValue] = useState(0)
  if (n !== prev) {
    setPrev(n)
    setValue(n)
  }
  console.log(value)
  return null
}
function App() {
  const [n, setN] = useState(1)
  useEffect(() => {
    setN(2)
  }, [])
  return <Child n={n} />
}

